import json, os, sys

LOGDIR = "/root/autodl-tmp/event-gated-adaptive-horizon/logdir"

experiments = {
    "healthy": {
        "exp_001_baseline_s3": "Baseline (no dt_emb)",
        "exp_008a_fixed_dt2_no_subsample": "Untrained dt_emb, subsample OFF",
        "exp_008e_v3_subsample_on_dt1_h15": "Untrained dt_emb, subsample ON, dt=1, H=15",
    },
    "collapsed": {
        "fixed_dt2_v1_s1": "Trained dt_emb, dt=2 (exp_006 equiv, first collapse)",
        "exp_008d_subsample_on_h8": "Trained dt_emb, subsample ON, H=8",
        "exp_008d_civo_trigger_s1": "CIVO trigger s1",
    }
}

results = {}

for group, exps in experiments.items():
    for exp_name, desc in exps.items():
        fpath = os.path.join(LOGDIR, exp_name, "metrics.jsonl")
        if not os.path.exists(fpath):
            print(f"MISSING: {fpath}", file=sys.stderr)
            continue
        data = []
        with open(fpath) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                rec = json.loads(line)
                if "actor_entropy" in rec:
                    data.append({
                        "step": rec.get("step"),
                        "actor_entropy": rec["actor_entropy"],
                        "train_return": rec.get("train_return"),
                    })
        results[exp_name] = {
            "group": group,
            "desc": desc,
            "n_records": len(data),
            "data": data
        }
        # summary stats
        if data:
            ents = [d["actor_entropy"] for d in data]
            steps = [d["step"] for d in data]
            print(f"\n=== {exp_name} ({group}) ===")
            print(f"  Desc: {desc}")
            print(f"  Records: {len(data)}, Steps: {steps[0]} - {steps[-1]}")
            print(f"  Entropy: min={min(ents):.4f}, max={max(ents):.4f}, mean={sum(ents)/len(ents):.4f}")
            # First 5, last 5
            print(f"  First 5 entropy: {[round(d['actor_entropy'],4) for d in data[:5]]}")
            print(f"  Last 5 entropy:  {[round(d['actor_entropy'],4) for d in data[-5:]]}")
            # Find inflection: biggest step-over-step change
            if len(ents) > 1:
                max_delta = 0
                max_delta_idx = 0
                for i in range(1, len(ents)):
                    delta = abs(ents[i] - ents[i-1])
                    if delta > max_delta:
                        max_delta = delta
                        max_delta_idx = i
                print(f"  Max delta: {max_delta:.4f} at step {steps[max_delta_idx]} (idx {max_delta_idx})")

# Save full data as JSON
with open("/tmp/entropy_data.json", "w") as f:
    json.dump(results, f)
print("\n\nFull data saved to /tmp/entropy_data.json")
PYEOF
